defmodule Gateway.RateLimiter do
  use GenServer

  @window_ms 60_000
  @sweep_every_ms 30_000

  def start_link(opts),
    do: GenServer.start_link(__MODULE__, opts, name: Keyword.get(opts, :name, __MODULE__))

  def hit(server \\ __MODULE__, key, limit), do: GenServer.call(server, {:hit, key, limit})

  @impl true
  def init(opts) do
    every = Keyword.get(opts, :sweep_every_ms, @sweep_every_ms)
    Process.send_after(self(), :sweep, every)
    {:ok, %{buckets: %{}, sweep_every: every}}
  end

  @impl true
  def handle_call({:hit, key, limit}, _from, %{buckets: buckets} = state) do
    now = System.monotonic_time(:millisecond)
    {count, started} = Map.get(buckets, key, {0, now})

    {count, started} =
      if now - started >= @window_ms, do: {0, now}, else: {count, started}

    if count < limit do
      {:reply, :ok, %{state | buckets: Map.put(buckets, key, {count + 1, started})}}
    else
      {:reply, {:error, :rate_limited}, state}
    end
  end

  @impl true
  def handle_info(:sweep, %{buckets: buckets, sweep_every: every} = state) do
    now = System.monotonic_time(:millisecond)
    live = Map.reject(buckets, fn {_key, {_count, started}} -> now - started >= @window_ms end)
    Process.send_after(self(), :sweep, every)
    {:noreply, %{state | buckets: live}}
  end
end

