import { readFileSync, statSync } from 'node:fs';

const SYNONYMS_PATH = new URL('../../data/synonyms.txt', import.meta.url);

let cached: { mtimeMs: number; map: Map<string, string[]> } | undefined;

export function loadSynonyms(): Map<string, string[]> {
  const { mtimeMs } = statSync(SYNONYMS_PATH);
  if (cached && cached.mtimeMs === mtimeMs) return cached.map;

  const map = new Map<string, string[]>();
  for (const line of readFileSync(SYNONYMS_PATH, 'utf8').split('\n')) {
    const [word, ...alts] = line.split(',').map((s) => s.trim()).filter(Boolean);
    if (word) map.set(word, alts);
  }
  cached = { mtimeMs, map };
  return map;
}

